 return b,np.linalg.inv(x.T@x)*(sse/df),sse,df

def raw_hessian(fun,theta,step):
 theta=np.array(theta,dtype=float);d=len(theta);h=step*(1+np.abs(theta));out=np.zeros((d,d));f=fun(theta)
